import{_ as o,l as n,o as t,c as s,v as e,p as l,x as r,d as p,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"实盘容量估计","description":"","frontmatter":{"title":"实盘容量估计","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/live-capacity-estimate.md","filePath":"quant/live-capacity-estimate.md","lastUpdated":1789023840000}'),c={name:"quant/live-capacity-estimate.md"};function m(h,a,E,u,_,B){const i=n("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="实盘容量估计" tabindex="-1">实盘容量估计 <a class="header-anchor" href="#实盘容量估计" aria-label="Permalink to &quot;实盘容量估计&quot;">​</a></h1><div class="epigraph"><p>纸面边缘随规模被冲击吃掉。容量是使净优势降到可接受下限的那条资产管理规模，而不是营销口径里的「市场足够深」。</p><footer>—— Perold and Salomon, The Right Amount of Assets Under Management, FAJ, 1991；Korajczyk and Sadka, Are Momentum Profits Robust to Trading Costs?, Journal of Finance, 2004；对照 Almgren 冲击与[容量与参与率](/quant/capacity-participation)</footer></div><p><a href="/quant/production-monitoring-alerts">上一课</a>要求监控去读容量曲线。主干<a href="/quant/capacity-participation">容量与参与率</a>已给出 \\(A\\) 与参与率 \\(p\\) 的代数。本课的缺口是<strong>用实盘观测校准这条曲线</strong>：登记的 \\(p\\) 上限、借券与保证金、制度掩码，如何从纸面 AUM 改成可部署 AUM。本课程「交易所、数据与工程」到此收束；下一课程中国市场进阶从产品制度继续，容量约束在那里不会变松。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>回测容量常假设：任意名字可按 ADV 的固定比例成交、空头免费、涨跌停不存在、特征不拥挤。实盘里 \\(V\\) 是同时与你竞争的流动性，不是历史 ADV；可借库存、期货保证金、程序化报撤上限都会先于 ADV 收紧。问题是估计 \\(\\mu_{\\mathrm{net}}(A)\\) 时必须用生产已实现的实施缺口成分（价差、延迟、拒单、部分成交）去替换回测里的冲击函数，否则容量是实验室数字。</p><p>Korajczyk 与 Sadka（2004）表明动量利润对交易成本假设敏感。推广：任何换手非零的策略，容量结论都属于冲击模型。应报告至少两套冲击（线性、平方根）以及一套「参与率封顶 + 制度掩码」的硬约束容量——往往更小。</p><h3 id="实盘样本短-曲线仍要画" tabindex="-1">实盘样本短，曲线仍要画 <a class="header-anchor" href="#实盘样本短-曲线仍要画" aria-label="Permalink to &quot;实盘样本短，曲线仍要画&quot;">​</a></h3><p>上线初期 \\(A\\) 小，观测不到平方根冲击的弯曲。不能因此声称容量无限。应用历史同类流量、券商成交分析、以及保守外推，并把「估计的不确定性」写成容量的折减，而不是等到冲击出现才减仓。监控课的参与率时间序列是校准数据：若实际 \\(p\\) 经常顶格，说明 \\(A\\) 已经碰到执行约束。</p><p><span class="marginnote">A 股容量还受：涨跌停不可成交、T+1 不能当日纠错、融券暂停、指数期货贴水与保证金、公募持仓披露与集中度。美股容量公式不能原样贴。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入：策略登记的宇宙与换手、生产实施缺口分解、借券费率分布、保证金与 VM 历史、制度掩码覆盖率（多少权重当日不可交易）。输出：使 \\(\\mu_{\\mathrm{net}}(A)\\) 等于费用后最低可接受值的 \\(A^\\ast\\)，以及先碰到的约束名称（冲击 / 借券 / 保证金 / 报撤 / 披露）。\\(A^\\ast\\) 随波动与制度改变，应定期重估，不是一年一次的营销数字。</p><p>与指数增强、中性策略的关系：跟踪误差预算与对冲工具容量可能先于个股 ADV 耗尽——后课中国指增与中性会用到。本课只要求：容量是约束的最小值，不是各约束分别估计再取最大。</p><h3 id="拥挤是内生的" tabindex="-1">拥挤是内生的 <a class="header-anchor" href="#拥挤是内生的" aria-label="Permalink to &quot;拥挤是内生的&quot;">​</a></h3><p>同一因子被多产品持有，\\(V\\) 里有你的同类。历史 ADV 高估可用流动性。可用换手、借券费、期货基差作为拥挤代理，把 \\(A^\\ast\\) 再折减。不要等到 2020 年 3 月或 2015 年股灾才承认折减。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>规模通过 \\(q=q(A)\\) 进入冲击 \\(g(q)\\)，再进入净优势。制度把 \\(q\\) 的可行集砍掉一块，等价于更陡的 \\(g\\)。工程（托管、低延迟）不增加 \\(A^\\ast\\) 的经济学上限，只减少延迟成分；若策略不是延迟敏感，工程对容量几乎无贡献。这纠正「买了托管就能做更大」的叙事。</p><p>清算与融资：haircut 与 VM 使杠杆策略的 \\(A^\\ast\\) 在压力日下降。容量应报告平静期与压力期两套，生产取压力期。</p>',17)),(t(),l(A,null,{default:r(()=>[d(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Paper%5B%22%E7%BA%B8%E9%9D%A2%E8%BE%B9%E7%BC%98%22%5D%20--%3E%20Impact%5B%22%E5%86%B2%E5%87%BB%E5%87%BD%E6%95%B0%20g(q)%22%5D%0A%20%20Inst%5B%22%E5%88%B6%E5%BA%A6%E6%8E%A9%E7%A0%81%20%E5%80%9F%E5%88%B8%20%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%20--%3E%20Feas%5B%22%E5%8F%AF%E8%A1%8C%20q%22%5D%0A%20%20Feas%20--%3E%20Impact%0A%20%20Impact%20--%3E%20Net%5B%22%E5%87%80%E4%BC%98%E5%8A%BF%20%CE%BC_net(A)%22%5D%0A%20%20Net%20--%3E%20Astar%5B%22%E5%8F%AF%E9%83%A8%E7%BD%B2%20AUM%22%5D%0A%20%20Live%5B%22%E5%AE%9E%E7%9B%98%E5%AE%9E%E6%96%BD%E7%BC%BA%E5%8F%A3%22%5D%20--%3E%20Impact%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供把参与率藏到监控阈值以下以虚增容量、或利用客户订单流信息扩大自身容量的方法。容量估计对外披露须与内部监控一致，避免两套数字。下一课程讨论中国产品时，容量数字必须用本课方法在 A 股约束下重算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>实盘容量用已实现缺口与制度硬约束校准，不单用历史 ADV。</li><li>\\(A^\\ast\\) 取所有约束的最小，并分平静/压力两套。</li><li>托管降延迟，不自动提高经济容量。</li><li>出处：Perold and Salomon, <em>FAJ</em>, 1991；Korajczyk and Sadka, <em>JF</em>, 2004；本栏容量课。</li></ul>',4))])}const D=o(c,[["render",m]]);export{f as __pageData,D as default};
